CREATE OR REPLACE FUNCTION atlas.bridge_push_to_prism(p_title text, p_description text, p_jurisdiction text, p_finding_summary text DEFAULT NULL::text, p_finding_confidence text DEFAULT 'medium'::text, p_finding_metadata jsonb DEFAULT NULL::jsonb, p_recommendation_action text DEFAULT NULL::text, p_recommendation_summary text DEFAULT NULL::text, p_source_table text DEFAULT NULL::text, p_source_record_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'atlas'
AS $function$
        DECLARE
            v_bridge RECORD;
            v_case_id UUID;
            v_finding_id UUID;
            v_rec_id UUID;
            v_start_ts TIMESTAMPTZ := clock_timestamp();
            v_response JSONB := '{}'::jsonb;
            v_log_id BIGINT;
            v_request_id BIGINT;
        BEGIN
            -- Get bridge config
            SELECT * INTO v_bridge FROM atlas.bridge_config 
            WHERE bridge_id = 'atlas-to-prism' AND enabled = true;

            IF v_bridge IS NULL THEN
                RETURN jsonb_build_object('error', 'Bridge atlas-to-prism not found or disabled');
            END IF;

            -- Generate UUIDs locally
            v_case_id := gen_random_uuid();
            v_finding_id := gen_random_uuid();
            v_rec_id := gen_random_uuid();

            -- Step 1: Create case in Prism via REST API
            SELECT net.http_post(
                url := v_bridge.target_url || '/rest/v1/cases',
                headers := jsonb_build_object(
                    'apikey', v_bridge.target_service_key,
                    'Authorization', 'Bearer ' || v_bridge.target_service_key,
                    'Content-Type', 'application/json',
                    'Prefer', 'return=representation'
                ),
                body := jsonb_build_object(
                    'id', v_case_id,
                    'title', p_title,
                    'description', p_description,
                    'jurisdiction', p_jurisdiction
                )
            ) INTO v_request_id;

            -- Log the case creation
            INSERT INTO atlas.bridge_sync_log (bridge_id, sync_type, source_table, source_record_id, target_table, target_record_id, status, request_payload, duration_ms)
            VALUES ('atlas-to-prism', 'create_case', p_source_table, p_source_record_id, 'cases', v_case_id::text, 'sent',
                jsonb_build_object('title', p_title, 'jurisdiction', p_jurisdiction),
                EXTRACT(MILLISECONDS FROM clock_timestamp() - v_start_ts)::integer
            ) RETURNING log_id INTO v_log_id;

            -- Step 2: Create finding if provided
            IF p_finding_summary IS NOT NULL THEN
                PERFORM net.http_post(
                    url := v_bridge.target_url || '/rest/v1/findings',
                    headers := jsonb_build_object(
                        'apikey', v_bridge.target_service_key,
                        'Authorization', 'Bearer ' || v_bridge.target_service_key,
                        'Content-Type', 'application/json',
                        'Prefer', 'return=representation'
                    ),
                    body := jsonb_build_object(
                        'id', v_finding_id,
                        'case_id', v_case_id,
                        'summary', p_finding_summary,
                        'confidence', p_finding_confidence,
                        'metadata', COALESCE(p_finding_metadata, '{}'::jsonb)
                    )
                );

                INSERT INTO atlas.bridge_sync_log (bridge_id, sync_type, source_table, source_record_id, target_table, target_record_id, status, request_payload)
                VALUES ('atlas-to-prism', 'create_finding', p_source_table, p_source_record_id, 'findings', v_finding_id::text, 'sent',
                    jsonb_build_object('case_id', v_case_id, 'summary', p_finding_summary));
            END IF;

            -- Step 3: Create recommendation if provided
            IF p_recommendation_summary IS NOT NULL THEN
                PERFORM net.http_post(
                    url := v_bridge.target_url || '/rest/v1/recommendations',
                    headers := jsonb_build_object(
                        'apikey', v_bridge.target_service_key,
                        'Authorization', 'Bearer ' || v_bridge.target_service_key,
                        'Content-Type', 'application/json',
                        'Prefer', 'return=representation'
                    ),
                    body := jsonb_build_object(
                        'id', v_rec_id,
                        'case_id', v_case_id,
                        'action_code', COALESCE(p_recommendation_action, 'REVIEW'),
                        'summary', p_recommendation_summary
                    )
                );

                INSERT INTO atlas.bridge_sync_log (bridge_id, sync_type, source_table, source_record_id, target_table, target_record_id, status, request_payload)
                VALUES ('atlas-to-prism', 'create_recommendation', p_source_table, p_source_record_id, 'recommendations', v_rec_id::text, 'sent',
                    jsonb_build_object('case_id', v_case_id, 'action_code', p_recommendation_action));
            END IF;

            -- Update bridge last sync
            UPDATE atlas.bridge_config SET 
                last_sync_at = now(), 
                last_sync_status = 'success',
                last_sync_error = NULL,
                updated_at = now()
            WHERE bridge_id = 'atlas-to-prism';

            v_response := jsonb_build_object(
                'success', true,
                'case_id', v_case_id,
                'finding_id', v_finding_id,
                'recommendation_id', v_rec_id,
                'log_id', v_log_id
            );

            RETURN v_response;
        EXCEPTION WHEN OTHERS THEN
            -- Log failure
            INSERT INTO atlas.bridge_sync_log (bridge_id, sync_type, source_table, source_record_id, status, error_message)
            VALUES ('atlas-to-prism', 'create_case', p_source_table, p_source_record_id, 'error', SQLERRM);

            UPDATE atlas.bridge_config SET 
                last_sync_at = now(), 
                last_sync_status = 'error',
                last_sync_error = SQLERRM,
                updated_at = now()
            WHERE bridge_id = 'atlas-to-prism';

            RETURN jsonb_build_object('error', SQLERRM);
        END;
        $function$

CREATE OR REPLACE FUNCTION atlas.bridge_sync_all_to_lighthouse()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'atlas'
AS $function$
DECLARE
    v_signals INT;
    v_entities INT;
    v_cases INT;
    v_pins INT;
    v_resources INT;
BEGIN
    -- Signals are auto-synced via trigger, but we can force a rebuild
    SELECT COUNT(*) INTO v_signals FROM lighthouse_signals WHERE lighthouse_status = 'new';

    -- Entities are auto-synced via trigger
    SELECT COUNT(*) INTO v_entities FROM lighthouse_entities WHERE risk_tier IN ('high', 'critical');

    -- Cases are auto-synced via trigger
    SELECT COUNT(*) INTO v_cases FROM lighthouse_cases WHERE case_status IN ('open', 'investigating');

    -- Rebuild map pins
    SELECT bridge_rebuild_map_pins() INTO v_pins;

    -- Push resources
    SELECT bridge_push_resources_to_lighthouse() INTO v_resources;

    RETURN jsonb_build_object(
        'signals_synced', v_signals,
        'high_risk_entities', v_entities,
        'active_cases', v_cases,
        'map_pins_rebuilt', v_pins,
        'resource_pins', v_resources,
        'synced_at', NOW()
    );
END;
$function$

CREATE OR REPLACE FUNCTION atlas.bridge_sync_all_to_lighthouse_v3()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'atlas'
AS $function$
DECLARE
    v_result JSONB;
BEGIN
    v_result := atlas.bridge_process_queue_v3(50);
    RETURN jsonb_build_object(
        'queue_processed', v_result,
        'synced_at', NOW()
    );
END;
$function$
